class Solution {
public:
    void InsertionSort(vector<int>& nums, int size, int n = 0){
        if(size==0) return;
        if(n==size-1) return;
        int i = n+1;
        while(i>=1 and nums[i-1]>nums[i]){
            swap(nums[i-1],nums[i]);
            i--;
        }
        InsertionSort(nums,size,++n);
    }
public:
    vector<int> insertionSort(vector<int>& nums) {
        InsertionSort(nums,nums.size());
        return nums;
    }
};

